from scipy.optimize import least_squares
import itertools
D={'t':t,'x':x,'v':v}
res=[]
for u,w in itertools.permutations(['t','x','v'],2):
  for form in ['exp*pow','pow*pow','exp*exp']:
    def model(p):
        a,b,k,c,d,e=p
        base=a*t+b/(1+k*x)/v
        if form=='exp*pow': f=np.exp(-d*D[u])*D[w]**e
        elif form=='pow*pow': f=D[u]**d*D[w]**e
        else: f=np.exp(-d*D[u])*np.exp(-e*D[w])
        return base+c*f
    bestr=None
    for s in range(15):
        p0=np.random.RandomState(s).uniform(-2,2,6)
        try:
            r=least_squares(lambda p: model(p)-y,p0)
            if np.isfinite(r.cost) and (bestr is None or r.cost<bestr.cost): bestr=r
        except Exception: pass
    if bestr is not None:
        res.append((np.mean((model(bestr.x)-y)**2)/np.var(y),u,w,form,bestr.x.round(4)))
res.sort(key=lambda z:z[0])
for r in res[:6]: print(r)

